export const INVITE_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Patholy · Customer invitation</title><link rel=\"stylesheet\" href=\"/invite/style.css\"><script src=\"/invite/app.js\" defer></script></head><body class=\"invite-page\"><main class=\"invite-card\"><span class=\"eyebrow\">PATHOLY MANAGEMENT SYSTEM</span><h1>Accept your invitation</h1><p>Your customer account uses the identity you verified through Cloudflare Access. No application password is created.</p><p id=\"invite-status\" role=\"status\" aria-live=\"polite\">Checking invitation…</p><button id=\"accept-invite\" disabled>Accept invitation</button><p>This links licensing access only. It does not share patient data or activate a desktop installation.</p></main></body></html>\r\n";
export const INVITE_JS="'use strict';\nlet token=new URLSearchParams(location.hash.slice(1)).get('token');history.replaceState(null,'',location.pathname);const status=document.getElementById('invite-status'),button=document.getElementById('accept-invite');if(token&&token.length>=32&&token.length<=256){status.textContent='Confirm to link this invitation to your verified customer identity.';button.disabled=false;}else{token=null;status.textContent='Invitation missing or invalid. Ask your licence administrator for a new invitation link.';}button.addEventListener('click',async()=>{button.disabled=true;try{const response=await fetch('/v1/customer/accept-invite',{method:'POST',credentials:'same-origin',redirect:'error',headers:{'Content-Type':'application/json','X-Patholy-Owner-Action':'1'},body:JSON.stringify({token})});let result;try{result=await response.json();}catch{throw new Error('Your identity session may have expired. Sign in again and reopen your invitation.');}if(!response.ok)throw new Error('Invitation could not be accepted. Check your signed-in identity, or request a new invitation.');token=null;status.textContent='Invitation accepted. Your verified identity is linked to the customer account.';button.hidden=true;}catch(error){status.textContent=error.message;button.disabled=false;}});\r\n";
